#include "PluginEditor.h"

#include <array>

MadronAudioProcessorEditor::MadronAudioProcessorEditor(MadronAudioProcessor& processor) : AudioProcessorEditor(&processor), processor_(processor) {
    title_.setText("Madron · P03", juce::dontSendNotification); title_.setFont(24.0f); title_.setJustificationType(juce::Justification::centred);
    status_.setText("Dynamic random DSP graph", juce::dontSendNotification); status_.setJustificationType(juce::Justification::centred);
    graphLabel_.setJustificationType(juce::Justification::centredLeft); graphLabel_.setMinimumHorizontalScale(0.65f);
    seedLabel_.setText("Seed",juce::dontSendNotification); seedInput_.setText(juce::String(processor_.recipeSeed()),false);nodeIdInput_.setText("2",false);parameterIdInput_.setText("formant.shift_cents",false);
    for(int i=0;i<10;++i)category_.addItem(madron::random::RecipeGenerator::categoryName(static_cast<madron::random::RecipeCategory>(i)),i+1);category_.setSelectedId(6);category_.onChange=[this]{processor_.setRecipeCategory(static_cast<madron::random::RecipeCategory>(category_.getSelectedId()-1));};
    performance_.addItem("Eco",1);performance_.addItem("Balanced",2);performance_.addItem("Extreme",3);performance_.setSelectedId(2);performance_.onChange=[this]{processor_.setPerformanceMode(static_cast<madron::random::PerformanceMode>(performance_.getSelectedId()-1));};
    auto slider=[&](juce::Slider& s,double lo,double hi,double step,auto setter){s.setRange(lo,hi,step);s.setValue((lo+hi)*0.5,juce::dontSendNotification);s.onValueChange=[&s,setter]{setter(static_cast<float>(s.getValue()));};};
    slider(intensity_,0,100,1,[this](float v){processor_.setIntensity(v);}); slider(complexity_,0,100,1,[this](float v){processor_.setComplexity(v);}); slider(wet_,0,1,0.01,[this](float v){processor_.setGlobalWet(v);}); wet_.setValue(1.0,juce::dontSendNotification); slider(transition_,50,200,1,[this](float v){processor_.setTransitionMilliseconds(v);}); transition_.setValue(100,juce::dontSendNotification);
    for(auto* button:{&roll_,&undo_,&redo_,&favorite_,&restoreFavorite_,&save_,&load_,&structureLock_,&nodeLock_,&parameterLock_}){button->addListener(this);addAndMakeVisible(*button);} const std::array<juce::Component*,13> components{&title_,&status_,&graphLabel_,&seedLabel_,&seedInput_,&nodeIdInput_,&parameterIdInput_,&category_,&performance_,&intensity_,&complexity_,&wet_,&transition_};for(auto* component:components)addAndMakeVisible(*component);setSize(560,500);startTimerHz(5);
}
void MadronAudioProcessorEditor::buttonClicked(juce::Button* button){if(button==&roll_){processor_.setRecipeSeed(static_cast<std::uint64_t>(seedInput_.getText().getLargeIntValue()));processor_.rollRecipe();}else if(button==&undo_)processor_.undoRecipe();else if(button==&redo_)processor_.redoRecipe();else if(button==&favorite_)processor_.favoriteRecipe();else if(button==&restoreFavorite_)processor_.restoreFavorite();else if(button==&structureLock_)processor_.toggleStructureLock();else if(button==&nodeLock_)processor_.toggleNodeLock(static_cast<madron::random::NodeID>(nodeIdInput_.getText().getIntValue()));else if(button==&parameterLock_)processor_.toggleParameterLock(parameterIdInput_.getText().toStdString());else if(button==&save_){chooser_=std::make_unique<juce::FileChooser>("Save Madron Recipe",juce::File{},"*.json");chooser_->launchAsync(juce::FileBrowserComponent::saveMode|juce::FileBrowserComponent::canSelectFiles,[this](const juce::FileChooser& chooser){auto file=chooser.getResult();if(file!=juce::File{})file.replaceWithText(processor_.recipeJson());});}else if(button==&load_){chooser_=std::make_unique<juce::FileChooser>("Load Madron Recipe",juce::File{},"*.json");chooser_->launchAsync(juce::FileBrowserComponent::openMode|juce::FileBrowserComponent::canSelectFiles,[this](const juce::FileChooser& chooser){auto file=chooser.getResult();if(file.existsAsFile())processor_.loadRecipeJson(file.loadFileAsString());});}}
void MadronAudioProcessorEditor::timerCallback(){processor_.collectGraphRetirement();seedInput_.setText(juce::String(processor_.recipeSeed()),false);graphLabel_.setText(processor_.graphSummary(),juce::dontSendNotification);}
void MadronAudioProcessorEditor::paint(juce::Graphics& g){g.fillAll(juce::Colour(0xff15151a));g.setColour(juce::Colours::white);g.drawRect(getLocalBounds(),1);}
void MadronAudioProcessorEditor::resized(){auto a=getLocalBounds().reduced(14);title_.setBounds(a.removeFromTop(42));status_.setBounds(a.removeFromTop(24));graphLabel_.setBounds(a.removeFromTop(26));auto row=[&](int h){return a.removeFromTop(h);};auto r=row(30);seedLabel_.setBounds(r.removeFromLeft(40));seedInput_.setBounds(r.removeFromLeft(140));category_.setBounds(r.removeFromLeft(180));performance_.setBounds(r.removeFromLeft(150));r=row(38);roll_.setBounds(r.removeFromLeft(145));undo_.setBounds(r.removeFromLeft(75));redo_.setBounds(r.removeFromLeft(75));favorite_.setBounds(r.removeFromLeft(80));restoreFavorite_.setBounds(r.removeFromLeft(120));r=row(32);structureLock_.setBounds(r.removeFromLeft(120));nodeIdInput_.setBounds(r.removeFromLeft(55));nodeLock_.setBounds(r.removeFromLeft(90));parameterIdInput_.setBounds(r.removeFromLeft(160));parameterLock_.setBounds(r.removeFromLeft(120));r=row(36);save_.setBounds(r.removeFromLeft(120));load_.setBounds(r.removeFromLeft(120));intensity_.setBounds(row(48));complexity_.setBounds(row(48));wet_.setBounds(row(48));transition_.setBounds(row(48));}
